@RestController @Profile("!mock") @RequestMapping("/api/v1/purchases/manage") @Transactional
class PurchaseManagementController {
 final PurchaseService service; final PurchaseRepository repo; final JdbcClient jdbc; final ObjectMapper json;
 final CatalogImageGateway images; final AuditHistoryLookup history; final AuditTrail audit;
 PurchaseManagementController(PurchaseService service,PurchaseRepository repo,JdbcClient jdbc,ObjectMapper json,CatalogImageGateway images,AuditHistoryLookup history,AuditTrail audit){this.service=service;this.repo=repo;this.jdbc=jdbc;this.json=json;this.images=images;this.history=history;this.audit=audit;}
 record Filters(String type,String status,String q,String supplier,String createdFrom,String createdTo,String deliveryFrom,String deliveryTo,String delivery,String logistics){}
 record Page<T>(List<T> items,long total,int page,int size){}
 record Save(@NotBlank @Size(max=100) String requestId,@Size(max=36) String id,@NotNull PurchaseController.OrderRequest order,@Size(max=36) String copyFromId){}
 record Selection(Filters filters,@Size(max=100) List<@NotBlank String> ids){}
 record ShipmentLine(String orderLineId,BigDecimal quantity,BigDecimal receivedQuantity){}
 record Shipment(String id,String carrier,String trackingNumber,String imageId,LocalDate shippedOn,int packageCount,String remark,long version,List<ShipmentLine> lines){}
 record ShipmentInput(@NotBlank @Size(max=100) String requestId,@Min(0) long version,@Size(max=100) String carrier,@Size(max=64) String trackingNumber,@Size(max=36) String imageId,@NotNull LocalDate shippedOn,@Min(1) int packageCount,@Size(max=500) String remark,@NotEmpty @Size(max=200) List<@NotNull ReceiptLineInput> lines){}
 static void require(boolean ok,String message){if(!ok)throw new PurchaseException(400,"PURCHASE_FIELD_INVALID",message);}
 static String safe(String v){return v==null?"":v.trim();}
 void paging(int page,int size){require(page>=0&&page<=100000&&Set.of(10,20,50,100).contains(size),"分页参数无效");}
 String hash(Object v){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(v)));}catch(Exception e){throw new IllegalStateException(e);}}
 @GetMapping("/capabilities") @PreAuthorize("hasAuthority('purchases.read')") Map<String,Integer> capabilities(){return Map.of("closeoutVersion",1);}
 private String where(Filters f,Map<String,Object> p){
  if(f==null)return " WHERE 1=1";StringBuilder w=new StringBuilder(" WHERE 1=1");
  if(!safe(f.type()).isEmpty()){require(Set.of("PRODUCT","MATERIAL","MANUAL").contains(f.type()),"采购类型无效");w.append(" AND o.order_type=:type");p.put("type",f.type());}
  if(!safe(f.status()).isEmpty()){if(f.status().equals("OPEN"))w.append(" AND o.status IN ('SUBMITTED','PARTIALLY_RECEIVED')");else{require(Arrays.stream(Status.values()).anyMatch(s->s.name().equals(f.status())),"状态无效");w.append(" AND o.status=:status");p.put("status",f.status());}}
  if(!safe(f.q()).isEmpty()){require(f.q().length()<=200,"搜索内容过长");w.append(" AND (LOWER(o.order_no) LIKE :q ESCAPE '!' OR LOWER(COALESCE(o.supplier_name,s.name,'')) LIKE :q ESCAPE '!' OR LOWER(COALESCE(o.tracking_number,'')) LIKE :q ESCAPE '!' OR EXISTS(SELECT 1 FROM purchase_order_line x WHERE x.order_id=o.id AND (LOWER(x.item_name) LIKE :q ESCAPE '!' OR LOWER(x.item_code) LIKE :q ESCAPE '!')) OR EXISTS(SELECT 1 FROM purchase_shipment x WHERE x.order_id=o.id AND LOWER(x.tracking_number) LIKE :q ESCAPE '!'))");p.put("q","%"+safe(f.q()).toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%");}
  if(!safe(f.supplier()).isEmpty()){w.append(" AND o.supplier_id=:supplier");p.put("supplier",f.supplier());}
  String[] values={f.createdFrom(),f.createdTo(),f.deliveryFrom(),f.deliveryTo()};String[] names={"createdFrom","createdTo","deliveryFrom","deliveryTo"};String[] expressions={"o.created_at>=:createdFrom","o.created_at<:createdTo","o.expected_delivery_date>=:deliveryFrom","o.expected_delivery_date<=:deliveryTo"};
  for(int i=0;i<4;i++)if(!safe(values[i]).isEmpty()){try{var d=LocalDate.parse(values[i]);p.put(names[i],i==1?d.plusDays(1):d);w.append(" AND ").append(expressions[i]);}catch(Exception e){throw new PurchaseException(400,"PURCHASE_FIELD_INVALID","日期无效");}}
  if("overdue".equals(f.delivery())){w.append(" AND o.status IN ('SUBMITTED','PARTIALLY_RECEIVED') AND o.expected_delivery_date<:today");p.put("today",LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")));}
  if("missing".equals(f.delivery()))w.append(" AND o.expected_delivery_date IS NULL");
  if("missing".equals(f.logistics()))w.append(" AND COALESCE(o.tracking_number,'')='' AND o.waybill_image_id IS NULL AND NOT EXISTS(SELECT 1 FROM purchase_shipment x WHERE x.order_id=o.id)");
  return w.toString();
 }
 final String from=" FROM purchase_order o LEFT JOIN supplier s ON s.id=o.supplier_id";
 Page<OrderView> page(Filters f,int page,int size,boolean limited){if(limited)paging(page,size);Map<String,Object> p=new HashMap<>();String w=where(f,p);long total=jdbc.sql("SELECT COUNT(*)"+from+w).params(p).query(Long.class).single();p.put("size",size);p.put("offset",(long)page*size);
  var heads=jdbc.sql("SELECT o.*,CASE WHEN o.snapshot_saved THEN COALESCE(o.supplier_name,'未填写') ELSE COALESCE(s.name,o.supplier_name,'未填写') END AS resolved_supplier_name"+from+w+" ORDER BY o.updated_at DESC,o.id DESC LIMIT :size OFFSET :offset").params(p).query(repo::mapOrder).list();
  var lines=repo.linesFor(heads.stream().map(OrderView::id).toList());return new Page<>(heads.stream().map(o->repo.withLines(o,lines.getOrDefault(o.id(),List.of()))).toList(),total,page,size);
 }
 @GetMapping("/orders") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 Page<OrderView> orders(@ModelAttribute Filters filters,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return page(filters,page,size,true);}
 @GetMapping("/counts") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 Map<String,Long> counts(){Map<String,Long> result=new HashMap<>();jdbc.sql("SELECT order_type,COUNT(*) n FROM purchase_order GROUP BY order_type").query((r,n)->{result.put(r.getString(1),r.getLong(2));return 0;}).list();return result;}
 @PostMapping("/save") @PreAuthorize("hasAuthority('purchases.write')")
 OrderView save(@Valid @RequestBody Save input,@AuthenticationPrincipal AuthenticatedActor actor,org.springframework.security.core.Authentication auth){
  jdbc.sql("SELECT id FROM iam_user WHERE id=:id FOR UPDATE").param("id",actor.userId()).query(String.class).single();
  var old=jdbc.sql("SELECT order_id,payload_hash FROM purchase_write_request WHERE actor_id=:actor AND request_id=:key").param("actor",actor.userId()).param("key",input.requestId()).query((r,n)->new String[]{r.getString(1),r.getString(2)}).optional();
  if(old.isPresent()){if(!old.get()[1].equals(hash(input)))throw new PurchaseException(409,"PURCHASE_REQUEST_CONFLICT","原请求内容不可修改");return service.order(old.get()[0]);}
  if((input.id()==null||service.order(input.id()).status()==Status.DRAFT)&&auth.getAuthorities().stream().noneMatch(a->a.getAuthority().equals("purchases.submit")))throw new PurchaseException(403,"CAPABILITY_DENIED","创建并下单或提交草稿需要采购下单权限");
  var command=input.order().input();require(command.lines()!=null&&!command.lines().isEmpty()&&command.lines().stream().allMatch(Objects::nonNull),"采购明细不能为空");OrderView saved;
  if(input.id()==null&&input.copyFromId()!=null&&command.orderType()==OrderType.MANUAL){
   var source=service.order(input.copyFromId());Set<String> allowed=new HashSet<>();source.lines().forEach(l->{if(l.imageAssetId()!=null)allowed.add(l.imageAssetId());});
   var lines=command.lines().stream().map(l->new LineInput(l.itemId(),l.quantity(),l.unitPrice(),l.itemName(),l.unit(),l.specification(),allowed.contains(l.imageAssetId())?null:l.imageAssetId(),l.taxIncluded(),l.taxRate(),l.packageCount())).toList();
   saved=service.place(new OrderInput(command.orderType(),command.supplierId(),command.currency(),command.remark(),null,lines,command.expectedDeliveryDate(),command.deliveryAddress(),command.supplierName()),actor);
   for(int i=0;i<command.lines().size();i++){var l=command.lines().get(i);if(allowed.contains(l.imageAssetId())){String image=images.copyForPurchase(l.imageAssetId(),saved.id(),actor);jdbc.sql("UPDATE purchase_order_line SET image_asset_id=:image WHERE order_id=:id AND line_no=:n").param("image",image).param("id",saved.id()).param("n",i+1).update();}}
   saved=service.order(saved.id());
  }else saved=input.id()==null?service.place(command,actor):service.updateAndPlace(input.id(),command,actor);
  jdbc.sql("INSERT INTO purchase_write_request(actor_id,request_id,payload_hash,order_id) VALUES(:actor,:key,:hash,:id)").param("actor",actor.userId()).param("key",input.requestId()).param("hash",hash(input)).param("id",saved.id()).update();return saved;
 }
 @GetMapping("/{id}/history") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 AuditHistoryLookup.HistoryPage history(@PathVariable String id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){paging(page,size);service.order(id);return history.page("PURCHASE",id,page+1,size);}
 @GetMapping("/{id}/receipts") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 Page<Map<String,Object>> receipts(@PathVariable String id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){paging(page,size);service.order(id);var heads=jdbc.sql("SELECT id,shipment_id FROM purchase_receipt WHERE order_id=:id ORDER BY created_at DESC,id DESC LIMIT :size OFFSET :offset").param("id",id).param("size",size).param("offset",(long)page*size).query((r,n)->new String[]{r.getString(1),r.getString(2)}).list();return new Page<>(heads.stream().map(v->{Map<String,Object> m=new HashMap<>();m.put("receipt",repo.receipt(v[0],false));m.put("shipmentId",v[1]);return m;}).toList(),jdbc.sql("SELECT COUNT(*) FROM purchase_receipt WHERE order_id=:id").param("id",id).query(Long.class).single(),page,size);}
 @GetMapping("/references") @PreAuthorize("hasAuthority('purchases.write')") @Transactional(readOnly=true)
 Page<ReferenceItem> references(@RequestParam OrderType type,@RequestParam String supplier,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){paging(page,size);require(type!=OrderType.MANUAL,"日常采购无需档案选择");repo.activeSupplier(supplier);repo.requireSupplierCategory(supplier,type);
  String table=type==OrderType.PRODUCT?" FROM product_variant v JOIN product p ON p.id=v.product_id JOIN product_variant_supplier r ON r.variant_id=v.id WHERE p.deleted_at IS NULL AND v.deleted_at IS NULL AND p.status='ACTIVE' AND v.status='ACTIVE'":" FROM auxiliary_material v JOIN auxiliary_material_supplier r ON r.auxiliary_material_id=v.id WHERE v.status='ACTIVE'";
  String name=type==OrderType.PRODUCT?"v.variant_name":"v.name",code=type==OrderType.PRODUCT?"v.sku_code":"v.material_code",image=type==OrderType.PRODUCT?"v.main_image_asset_id":"v.image_asset_id",url=type==OrderType.PRODUCT?"v.main_image_url":"v.image_url",unit=type==OrderType.PRODUCT?"'件'":"v.unit";
  String w=table+" AND r.supplier_id=:supplier AND (LOWER("+name+") LIKE :q ESCAPE '!' OR LOWER("+code+") LIKE :q ESCAPE '!')";var params=Map.<String,Object>of("supplier",supplier,"q","%"+safe(q).toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%");long total=jdbc.sql("SELECT COUNT(*)"+w).params(params).query(Long.class).single();var rows=jdbc.sql("SELECT v.id,"+code+" code,"+name+" name,"+unit+" unit,"+image+" image,"+url+" url,r.primary_slot"+w+" ORDER BY name,v.id LIMIT :size OFFSET :offset").params(params).param("size",size).param("offset",(long)page*size).query((r,n)->new ReferenceItem(r.getString("id"),r.getString("code"),r.getString("name"),r.getString("unit"),"PRIMARY".equals(r.getString("primary_slot")),r.getString("image"),r.getString("url"))).list();return new Page<>(rows,total,page,size);
 }
 @GetMapping("/price") @PreAuthorize("hasAuthority('purchases.write')") @Transactional(readOnly=true)
 Map<String,Object> price(@RequestParam String item,@RequestParam String supplier,@RequestParam String currency){var rows=jdbc.sql("SELECT l.unit_price,l.tax_included,l.tax_rate,l.unit,o.order_no,o.created_at FROM purchase_order_line l JOIN purchase_order o ON o.id=l.order_id WHERE l.item_id=:item AND o.supplier_id=:supplier AND o.currency=:currency AND o.status IN ('SUBMITTED','PARTIALLY_RECEIVED','COMPLETED') ORDER BY o.created_at DESC,o.id DESC LIMIT 1").param("item",item).param("supplier",supplier).param("currency",currency).query((r,n)->Map.<String,Object>of("unitPrice",r.getBigDecimal(1),"taxIncluded",r.getBoolean(2),"taxRate",r.getBigDecimal(3),"unit",r.getString(4),"orderNo",r.getString(5),"createdAt",r.getTimestamp(6).toInstant().toString())).list();return rows.isEmpty()?Map.of():rows.get(0);}
 @GetMapping("/{id}/product-parent") @PreAuthorize("hasAuthority('purchases.read') and hasAuthority('products.read')") @Transactional(readOnly=true)
 Map<String,String> parent(@PathVariable String id,@RequestParam String item){var o=service.order(id);require(o.orderType()==OrderType.PRODUCT&&o.lines().stream().anyMatch(l->l.itemId().equals(item)),"商品不属于该采购单");return Map.of("parentId",jdbc.sql("SELECT product_id FROM product_variant WHERE id=:id AND deleted_at IS NULL").param("id",item).query(String.class).optional().orElseThrow(()->new PurchaseException(404,"SKU_NOT_FOUND","当前产品已删除，采购留存资料仍可查看")));}
 @GetMapping("/{id}/checks") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 List<String> checks(@PathVariable String id){var order=service.order(id);List<String> result=new ArrayList<>();if(order.orderType()==OrderType.MANUAL)return result;try{repo.activeSupplier(order.supplierId());repo.requireSupplierCategory(order.supplierId(),order.orderType());}catch(PurchaseException e){result.add(e.getMessage()+"；既有收货不依赖新增供货关系");}
  for(var line:order.lines()){String relation=order.orderType()==OrderType.PRODUCT?"SELECT COUNT(*) FROM product_variant v JOIN product p ON p.id=v.product_id JOIN product_variant_supplier r ON r.variant_id=v.id WHERE v.id=:item AND r.supplier_id=:supplier AND v.status='ACTIVE' AND p.status='ACTIVE' AND v.deleted_at IS NULL AND p.deleted_at IS NULL":"SELECT COUNT(*) FROM auxiliary_material v JOIN auxiliary_material_supplier r ON r.auxiliary_material_id=v.id WHERE v.id=:item AND r.supplier_id=:supplier AND v.status='ACTIVE'";if(jdbc.sql(relation).param("item",line.itemId()).param("supplier",order.supplierId()).query(Long.class).single()==0){result.add(line.itemName()+"：档案停用、删除或供货关系变化，请核对；新增或增加采购需先维护关系");}if(order.orderType()==OrderType.MATERIAL){String unit=jdbc.sql("SELECT unit FROM auxiliary_material WHERE id=:id").param("id",line.itemId()).query(String.class).optional().orElse("");if(!line.unit().equalsIgnoreCase(unit))result.add(line.itemName()+"：当前单位与订单单位不同，不能直接混合入库，请先恢复正确单位或关闭余量");}}return result;
 }
 @GetMapping("/{id}/shipments") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 List<Shipment> shipments(@PathVariable String id){service.order(id);return jdbc.sql("SELECT * FROM purchase_shipment WHERE order_id=:id ORDER BY created_at,id").param("id",id).query((r,n)->new Shipment(r.getString("id"),r.getString("carrier"),r.getString("tracking_number"),r.getString("image_id"),r.getObject("shipped_on",LocalDate.class),r.getInt("package_count"),r.getString("remark"),r.getLong("version"),shipmentLines(r.getString("id")))).list();}
 List<ShipmentLine> shipmentLines(String id){return jdbc.sql("SELECT * FROM purchase_shipment_line WHERE shipment_id=:id ORDER BY order_line_id").param("id",id).query((r,n)->new ShipmentLine(r.getString("order_line_id"),r.getBigDecimal("quantity"),r.getBigDecimal("received_quantity"))).list();}
 @PostMapping("/{id}/shipments") @PreAuthorize("hasAuthority('purchases.write')")
 List<Shipment> shipment(@PathVariable String id,@Valid @RequestBody ShipmentInput input,@AuthenticationPrincipal AuthenticatedActor actor){var order=repo.find(id,true).orElseThrow(()->new PurchaseException(404,"PURCHASE_ORDER_NOT_FOUND","采购单不存在"));var prior=jdbc.sql("SELECT payload_hash,order_id FROM purchase_shipment WHERE actor_id=:actor AND request_id=:key").param("actor",actor.userId()).param("key",input.requestId()).query((r,n)->new String[]{r.getString(1),r.getString(2)}).optional();if(prior.isPresent()){require(prior.get()[0].equals(hash(input))&&prior.get()[1].equals(id),"原发货请求内容不可改变");return shipments(id);}
  if(order.version()!=input.version())throw new PurchaseException(409,"PURCHASE_VERSION_CONFLICT","采购单已更新，请刷新后重新核对本批发货数量");require(Set.of(Status.SUBMITTED,Status.PARTIALLY_RECEIVED).contains(order.status()),"该采购单不能登记发货");require(!safe(input.trackingNumber()).isEmpty()||input.imageId()!=null,"运单号与图片至少一项");require(safe(input.trackingNumber()).isEmpty()||input.trackingNumber().matches("[A-Za-z0-9-]{1,64}"),"运单号格式无效");require(!input.shippedOn().isAfter(LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"))),"发货日期不能在未来");
  String shipmentId=UUID.randomUUID().toString();Set<String> ids=new HashSet<>();for(var l:input.lines()){require(ids.add(l.orderLineId()),"发货明细重复");var line=order.lines().stream().filter(v->v.id().equals(l.orderLineId())).findFirst().orElseThrow(()->new PurchaseException(400,"PURCHASE_LINE_ORDER_MISMATCH","发货项目不属于该单"));PurchaseCloseout.quantity(order.orderType(),line.unit(),l.quantity());BigDecimal allocated=jdbc.sql("SELECT COALESCE(SUM(quantity-received_quantity),0) FROM purchase_shipment_line WHERE order_line_id=:id").param("id",line.id()).query(BigDecimal.class).single();require(l.quantity().compareTo(line.remainingQuantity().subtract(allocated))<=0,"发货数量超过尚未分配的采购余量");}
  jdbc.sql("INSERT INTO purchase_shipment(id,order_id,request_id,payload_hash,actor_id,carrier,tracking_number,image_id,shipped_on,package_count,remark) VALUES(:id,:order,:key,:hash,:actor,:carrier,:tracking,:image,:date,:packages,:remark)").param("id",shipmentId).param("order",id).param("key",input.requestId()).param("hash",hash(input)).param("actor",actor.userId()).param("carrier",input.carrier()).param("tracking",input.trackingNumber()).param("image",input.imageId()).param("date",input.shippedOn()).param("packages",input.packageCount()).param("remark",input.remark()).update();
  for(var l:input.lines())jdbc.sql("INSERT INTO purchase_shipment_line(shipment_id,order_line_id,quantity) VALUES(:id,:line,:q)").param("id",shipmentId).param("line",l.orderLineId()).param("q",l.quantity()).update();
  images.attach(input.imageId(),CatalogImageGateway.Purpose.PURCHASE_WAYBILL,"PURCHASE_SHIPMENT",shipmentId,actor);jdbc.sql("UPDATE purchase_order SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id").param("id",id).update();audit.record(new AuditTrail.BusinessOperation(actor.userId(),actor.loginName(),actor.displayName(),"PURCHASE_SHIPMENT_CREATE","PURCHASE",id,true,null,Map.of("shipmentId",shipmentId,"trackingNumber",safe(input.trackingNumber()),"packageCount",input.packageCount(),"lines",input.lines()),"登记发货批次"));return shipments(id);
 }
 List<OrderView> selected(Selection input,int limit){if(input.ids()!=null&&!input.ids().isEmpty())return input.ids().stream().distinct().map(service::order).toList();var result=page(input.filters(),0,limit,false);require(result.total()<=limit,"导出数量过多，请缩小筛选范围");return result.items();}
 @PostMapping("/selection") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 List<OrderView> selection(@Valid @RequestBody Selection input){var rows=selected(input,100);require(rows.stream().mapToInt(o->o.lines().size()).sum()<=1000,"图片导出最多 1000 项，请分批选择");return rows;}
 @PostMapping(value="/export",produces="text/csv;charset=UTF-8") @PreAuthorize("hasAuthority('purchases.read')") @Transactional(readOnly=true)
 ResponseEntity<byte[]> export(@Valid @RequestBody Selection input){var rows=selected(input,2000);require(rows.stream().mapToInt(o->o.lines().size()).sum()<=20000,"一次最多导出 20000 条明细，请缩小范围");StringBuilder csv=new StringBuilder("\uFEFF采购单号,类型,供应商,状态,商品,规格,单位,采购数量,已收,未收或关闭余量,币种,未税单价,税率,税额,应付金额,交期,收货信息,备注\r\n");for(var o:rows)for(var l:o.lines()){BigDecimal net=l.orderedQuantity().multiply(l.unitPrice()),tax=l.taxIncluded()?net.multiply(l.taxRate()).movePointLeft(2):BigDecimal.ZERO,total=net.add(tax).setScale(2,RoundingMode.HALF_UP);csv.append(Arrays.asList(o.orderNo(),switch(o.orderType()){case PRODUCT->"产品";case MATERIAL->"辅料";case MANUAL->"日常物品";},o.supplierName(),switch(o.status()){case DRAFT->"草稿";case SUBMITTED->"待收货";case PARTIALLY_RECEIVED->"部分收货";case COMPLETED->"已完成";case CANCELLED->"已取消/余量关闭";},l.itemName(),l.specification(),l.unit(),l.orderedQuantity(),l.receivedQuantity(),l.remainingQuantity(),o.currency(),l.unitPrice(),l.taxIncluded()?l.taxRate():BigDecimal.ZERO,tax.setScale(2,RoundingMode.HALF_UP),total,o.expectedDeliveryDate(),o.deliveryAddress(),o.remark()).stream().map(PurchaseManagementController::csv).collect(java.util.stream.Collectors.joining(","))).append("\r\n");}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=purchases.csv").body(csv.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 static String csv(Object v){String s=v==null?"":v.toString(),t=s.stripLeading();if(!t.isEmpty()&&"=+-@".indexOf(t.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
}
